(()=>{
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=[{id:'studio',name:'Studio Merch',category:'Merchandise',city:'Delhi NCR',initial:'Sm.',art:'merch-art',about:'Apparel, printing, and event merchandise. Explore an illustrative portfolio of team kits and event essentials.',services:'Printed T-shirts, event kits, embroidery, branded merchandise',contact:'Aarav',email:'aarav@studio-merch.example',projects:[{title:'A coordinated team kit',type:'Illustrative project',year:'2025',description:'T-shirts, sizing coordination, and printed samples for a college organising team.'},{title:'Welcome kits with a consistent identity',type:'Illustrative project',year:'2026',description:'A coordinated set of printed apparel and welcome essentials.'}],reviews:[],sample:true},{id:'gather',name:'Gather Events',category:'Events & production',city:'Delhi NCR',initial:'gather',art:'event-art',about:'Event production, staging, and technical coordination. A sample profile showing how a contractor can present relevant past work.',services:'Stage production, sound, lighting, on-site coordination',contact:'Meera',email:'meera@gather-events.example',projects:[{title:'A stage built around the programme',type:'Illustrative project',year:'2026',description:'Stage planning, lighting cues, and technical coordination for a campus event.'}],reviews:[],sample:true},{id:'room',name:'Room & Co.',category:'Workspace services',city:'Delhi NCR',initial:'room&co',art:'space-art',about:'Furniture and fit-out services for offices and shared spaces. A sample portfolio that brings capabilities and delivery scope into focus.',services:'Office furniture, shared-space planning, installation',contact:'Kabir',email:'kabir@room-co.example',projects:[{title:'A shared space, thoughtfully organised',type:'Illustrative project',year:'2025',description:'Furniture selection, layout planning, and installation coordination.'}],reviews:[],sample:true}];
const detailExamples={studio:{tagline:'Made to bring your team together.',nature:'Apparel & merchandise studio',coverage:'Delhi NCR · delivery elsewhere by agreement',approach:'Brief and artwork review → printed sample approval → production → final quality check and delivery',capacity:'Small and medium event batches; quantities and lead times confirmed for each brief.',exclusions:'Artwork development, urgent production and individual packaging should be confirmed in the quotation.',quality:'Ask for fabric composition, GSM, a size chart and an approved printed sample.',projectScope:['Printed apparel · size coordination · artwork placement','Welcome kits · print consistency · packaging'],outcome:'An example of how a supplier can explain the scope and handover. No real client result is claimed.'},gather:{tagline:'Every detail, ready for showtime.',nature:'Event production agency',coverage:'Delhi NCR · venue feasibility required',approach:'Site discussion → technical plan → rehearsal and safety checks → on-site production → dismantling',capacity:'Production scale depends on the venue, programme and equipment availability.',exclusions:'Venue permissions, power supply, security and weather cover need written scope confirmation.',quality:'Ask for an equipment list, crew responsibilities, a run sheet and backup arrangements.',projectScope:['Stage planning · lighting cues · technical coordination'],outcome:'Illustrative delivery approach, not a verified event or client engagement.'},room:{tagline:'Spaces that work for the people in them.',nature:'Furniture & fit-out contractor',coverage:'Delhi NCR · on-site survey by arrangement',approach:'Measure and understand → layouts and material approval → supply and installation → snag review',capacity:'Scope and installation schedule depend on site readiness and agreed materials.',exclusions:'Civil works, electrical alterations and disposal should be priced separately if required.',quality:'Ask for material specifications, installation scope, warranty and a handover checklist.',projectScope:['Furniture selection · layout planning · installation'],outcome:'Illustrative portfolio scope; no real project outcome or performance metric is claimed.'}};
function profileDetails(s){return {...(detailExamples[s.id]||{}),...s};}
function detailFields(s={}){return `<details class="brief-fold"><summary><span><strong>Make your portfolio more useful</strong><small>Company details, service area & delivery approach · Optional</small></span><span>+</span></summary><div class="brief-fold-body">${[['tagline','One-line introduction','What do you want buyers to remember?'],['nature','Nature of company','Manufacturer, agency, contractor…'],['coverage','Service area & delivery coverage','Where can you deliver or work on site?'],['capacity','Order scale & lead times','Describe the work you take on; avoid guarantees you cannot confirm.'],['approach','How you work','Brief, approvals, production, delivery, handover…'],['quality','Quality & acceptance','How do you check quality and handle sign-off?'],['exclusions','What needs separate confirmation?','Travel, installation, taxes, permits, warranty…']].map(([key,label,hint])=>`<div class="field"><label for="business-${key}">${label}</label><textarea class="example-input" id="business-${key}" name="${key}" placeholder="${hint}">${safe(s[key]||'')}</textarea></div>`).join('')}</div></details>`;}
function portfolioDetailSections(raw){const s=profileDetails(raw);return `<section class="portfolio-overview"><div class="section-row"><div><span class="eyebrow">CAPABILITY, IN CONTEXT</span><h2>Get to know the business.</h2></div>${!s.sample?`<button class="button small" data-edit-business="${safe(s.id)}">Edit details ↗</button>`:''}</div><p class="portfolio-about-copy">${safe(s.about)}</p><div class="portfolio-facts"><div><span>COMPANY TYPE</span><strong>${safe(s.nature||'Not specified')}</strong></div><div><span>SERVICE COVERAGE</span><strong>${safe(s.coverage||s.city)}</strong></div><div><span>ORDER SCALE & LEAD TIMES</span><strong>${safe(s.capacity||'Ask the supplier about capacity and availability.')}</strong></div></div><div class="capability-tags">${s.services.split(',').map(t=>`<span>${safe(t.trim())}</span>`).join('')}</div></section><section class="portfolio-method"><span class="eyebrow">FROM YOUR BRIEF TO HANDOVER</span><h2>How the work comes together.</h2><p>${safe(s.approach||'The supplier has not added their process yet. Ask about planning, approvals, delivery, and handover.')}</p><div class="portfolio-assurances"><div><span>✳</span><h3>Quality & acceptance</h3><p>${safe(s.quality||'Request a clear acceptance checklist, warranty and support terms.')}</p></div><div><span>↗</span><h3>Confirm before committing</h3><p>${safe(s.exclusions||'Confirm taxes, delivery, exclusions, payment milestones and cancellation terms in writing.')}</p></div></div></section>`;}
let userProfiles=[],localReviews={};try{userProfiles=JSON.parse(localStorage.getItem('ql-supplier-profiles')||'[]');localReviews=JSON.parse(localStorage.getItem('ql-supplier-reviews')||'{}')}catch{}
const categories=['All categories','Merchandise','Events & production','Workspace services','Maintenance & construction','Catering & hospitality','Technology & services','Other'];let query='',category='All categories',focusBefore;let selectedId=null;
const main=document.getElementById('supplier-main');const modalRoot=document.getElementById('supplier-modal');const all=()=>[...seed,...userProfiles];
function persist(){try{localStorage.setItem('ql-supplier-profiles',JSON.stringify(userProfiles));localStorage.setItem('ql-supplier-reviews',JSON.stringify(localReviews));return true}catch{notify('Storage unavailable. Changes will last for this session only.');return false}}
function notify(t){const el=document.getElementById('supplier-toast');el.textContent=t;el.hidden=false;setTimeout(()=>el.hidden=true,4500)}
function modal(title,body){focusBefore=document.activeElement;modalRoot.innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="supplier-dialog-title"><div class="modal-head"><h2 id="supplier-dialog-title">${title}</h2><button class="close-button" data-close-supplier aria-label="Close">×</button></div>${body}</section></div>`;modalRoot.querySelector('.close-button').focus()}
function close(){modalRoot.innerHTML='';focusBefore?.focus()}
function supplierCard(s){const reviews=localReviews[s.id]||[];return `<article class="partner-card"><div class="partner-cover ${s.art||'merch-art'}"><span class="partner-monogram">${safe(s.initial||s.name.slice(0,2))}</span><span class="partner-category">${safe(s.category)}</span><span class="cover-ring" aria-hidden="true"></span></div><div class="partner-body"><div class="partner-title"><h3>${safe(s.name)}</h3><span>↗</span></div><p>${safe(s.about)}</p><div class="partner-tags"><span>${safe(s.city)}</span><span>${s.projects.length} portfolio ${s.projects.length===1?'project':'projects'}</span></div><div class="directory-review-count">${reviews.length?reviews.length+' local review'+(reviews.length>1?'s':''):'No client reviews yet'}</div><div class="partner-contact"><span>${s.sample?'Illustrative profile':'Your local draft profile'}</span><button class="button small" data-profile="${safe(s.id)}">Explore portfolio ↗</button></div></div></article>`;}
function results(){const found=all().filter(s=>(category==='All categories'||s.category===category)&&`${s.name} ${s.services} ${s.city} ${s.category}`.toLowerCase().includes(query.toLowerCase()));document.getElementById('supplier-results').innerHTML=found.length?found.map(supplierCard).join(''):'<div class="empty-state"><h2>No matching profiles.</h2><p>Try a broader service or location.</p></div>';document.getElementById('supplier-count').textContent=found.length+' matching profiles';}
function directory(){selectedId=null;main.innerHTML=`<section class="directory-hero"><div><span class="eyebrow"><span class="gold-star">✳</span> THE PEOPLE BEHIND THE PROPOSAL</span><h1>Find capability.<br><span>Then find your fit.</span></h1><p>Explore suppliers and contractors by what they do, what they’ve delivered, and what clients have to say.</p></div><aside><span class="directory-orb" aria-hidden="true">↗</span><span class="chip gold">FOR SUPPLIERS</span><h2>Your work deserves<br>a proper introduction.</h2><button class="text-link" data-supplier-signup>Create your portfolio →</button></aside></section><div class="directory-toolbar"><div class="field"><label for="supplier-search">Service, business, or location</label><input id="supplier-search" type="search" placeholder="Try merchandise, maintenance, or Delhi…" value="${safe(query)}"></div><div class="field"><label for="supplier-category">Category</label><select id="supplier-category">${categories.map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select></div></div><div class="section-row"><h2>Explore the directory</h2><span id="supplier-count" aria-live="polite"></span></div><div class="partner-grid directory-grid" id="supplier-results"></div><p class="directory-disclaimer">Sample profiles demonstrate the experience. Self-listed profiles and reviews in this preview are stored only in this browser, not published or verified.</p>`;results();document.getElementById('supplier-search').addEventListener('input',e=>{query=e.target.value;results()});document.getElementById('supplier-category').addEventListener('change',e=>{category=e.target.value;results()})}
function profile(id){const s=all().find(x=>x.id===id);if(!s){directory();return}selectedId=id;const d=profileDetails(s);const reviews=localReviews[id]||[];main.innerHTML=`<button class="back-directory" data-directory>← Explore suppliers</button><section class="profile-hero"><div class="profile-monogram ${s.art||'merch-art'}">${safe(s.initial||s.name.slice(0,2))}</div><div class="profile-title"><span class="eyebrow">${safe(s.category)} · ${safe(s.city)}</span><h1>${safe(s.name)}</h1><p class="portfolio-tagline">${safe(d.tagline||s.about)}</p><span class="chip ${s.sample?'neutral':'gold'}">${s.sample?'Illustrative profile':'Local draft · Not published'}</span></div><button class="button primary" data-request="${safe(id)}">Share your requirements ↗</button></section><div class="portfolio-summary-strip"><div><strong>${s.projects.length}</strong><span>Portfolio projects</span></div><div><strong>${reviews.length}</strong><span>Local client remarks</span></div><div><strong>${safe(s.city)}</strong><span>Based / serving</span></div><div><strong>${s.sample?'Sample profile':'Self-listed draft'}</strong><span>No verification claimed</span></div></div><nav class="portfolio-anchor-nav" aria-label="Portfolio sections"><a href="#about-business">About</a><a href="#selected-work">Projects</a><a href="#client-remarks">Client remarks</a></nav><div class="profile-layout"><section><div id="about-business">${portfolioDetailSections(s)}</div><div class="section-row" id="selected-work"><h2>Selected work</h2>${!s.sample?`<button class="button small" data-add-project="${safe(id)}">+ Add project</button>`:'<span>Illustrative portfolio</span>'}</div><div class="portfolio-grid">${s.projects.length?s.projects.map((p,i)=>`<article class="portfolio-project"><div class="project-visual ${i%2?'gold-visual':'lilac-visual'}"><span>${String(i+1).padStart(2,'0')}</span><small>${safe(p.year||'')}</small></div><div><span class="eyebrow">${safe(p.type||s.category)}</span><h3>${safe(p.title)}</h3><p>${safe(p.description)}</p><details class="project-case"><summary>Explore project details <span>↗</span></summary><div><h4>Scope of work</h4><p>${safe(p.scope||d.projectScope?.[i]||p.description)}</p><h4>Delivery & outcome</h4><p>${safe(p.outcome||d.outcome||'No outcome details added yet.')}</p><span class="chip neutral">${s.sample?'Illustrative project · Not a client claim':'Supplier-provided · Unverified'}</span></div></details></div></article>`).join(''):'<div class="portfolio-empty">Add your first completed project to show buyers what you can deliver.</div>'}</div><section class="reviews-section" id="client-remarks"><div class="section-row"><div><h2>Client remarks</h2><p>Feedback belongs with the work.</p></div><button class="button small" data-review="${safe(id)}">Write a review</button></div>${reviews.length?reviews.map(r=>`<article class="review-card"><div class="section-row"><strong>${safe(r.name)}</strong><span class="review-stars" aria-label="${r.rating} out of 5">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span></div><span class="review-project">${safe(r.project)} · ${safe(r.date)}</span><p>${safe(r.text)}</p><span class="chip neutral">Unverified · Local preview</span></article>`).join(''):'<div class="reviews-empty"><span>✳</span><h3>Let the work earn its words.</h3><p>No reviews yet. Prior clients can describe the project, delivery, quality, and communication.</p></div>'}<p class="directory-disclaimer">Production reviews will require client sign-in, a completed engagement reference, and moderation. Local reviews are not verified endorsements.</p></section></section><aside class="profile-aside"><span class="eyebrow">YOUR POINT OF CONTACT</span><div class="portfolio-contact-avatar">${safe(s.contact.slice(0,1))}</div><h3>${safe(s.contact)}</h3><p>Discuss scope, availability and a written quotation.</p><hr><h3>What they can help with</h3><p>${safe(s.services)}</p><hr><span>CONTACT PERSON</span><strong>${safe(s.contact)}</strong><span>EMAIL</span><p class="business-email">${safe(s.email)}</p><button class="button small" data-request="${safe(id)}">Prepare an enquiry ↗</button><small>${s.sample?'Sample contact. No live supplier connection.':'Profile saved locally. Authentication and publishing are not connected.'}</small></aside></div>`;}
function signup(){modal('Let your work introduce you.',`<p>Create a supplier portfolio draft. This preview saves locally; account verification and public listing will be added in the live service.</p><form id="supplier-signup"><div class="field-row"><div class="field"><label for="business-name">Business name</label><input id="business-name" name="name" required maxlength="90"></div><div class="field"><label for="business-city">Service area</label><input id="business-city" name="city" required placeholder="e.g. Delhi NCR"></div></div><div class="field"><label for="business-category">Business category</label><select id="business-category" name="category">${categories.slice(1).map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label for="business-about">Introduce your business</label><textarea id="business-about" name="about" required placeholder="What do you specialise in, and what do customers value about your work?"></textarea></div><div class="field"><label for="business-services">Services and capabilities</label><textarea id="business-services" name="services" required></textarea></div><div class="field-row"><div class="field"><label for="business-contact">Contact person</label><input id="business-contact" name="contact" required></div><div class="field"><label for="business-email">Business email</label><input id="business-email" name="email" type="email" required></div></div>${detailFields()}<button class="button primary small" type="submit">Create my profile draft →</button></form>`);document.getElementById('supplier-signup').addEventListener('submit',e=>{e.preventDefault();const s={...Object.fromEntries(new FormData(e.currentTarget)),id:crypto.randomUUID(),projects:[],reviews:[],sample:false};userProfiles.push(s);const saved=persist();close();location.hash=s.id;profile(s.id);notify(saved?'Supplier profile saved locally. Add your past work next.':'Profile created for this session; local storage unavailable.')})}
function editBusiness(id){const s=userProfiles.find(x=>x.id===id);if(!s)return;modal('Complete your company story.',`<form id="business-details-form">${detailFields(s)}<button class="button small primary" type="submit">Save portfolio details</button></form>`);modalRoot.querySelector('details').open=true;document.getElementById('business-details-form').addEventListener('submit',e=>{e.preventDefault();Object.assign(s,Object.fromEntries(new FormData(e.currentTarget)));persist();close();profile(id)})}
function addProject(id){const s=userProfiles.find(x=>x.id===id);if(!s)return;modal('Add a project to your portfolio.',`<form id="project-form"><div class="field"><label for="project-title">Project title</label><input id="project-title" name="title" required></div><div class="field-row"><div class="field"><label for="project-type">Type of work</label><input id="project-type" name="type" required></div><div class="field"><label for="project-year">Completion year</label><input id="project-year" name="year" type="number" min="1900" max="2100" required></div></div><div class="field"><label for="project-description">Scope and outcome</label><textarea id="project-description" name="description" required placeholder="What did you deliver? What made the project distinctive?"></textarea></div><div class="field"><label for="project-scope">What did you deliver? · Optional</label><textarea id="project-scope" name="scope" placeholder="Key deliverables, scale, materials, and your responsibilities."></textarea></div><div class="field"><label for="project-outcome">Outcome & handover · Optional</label><textarea id="project-outcome" name="outcome" placeholder="What was achieved? Include only results you can substantiate."></textarea></div><button class="button small primary" type="submit">Add project</button></form>`);document.getElementById('project-form').addEventListener('submit',e=>{e.preventDefault();s.projects.push(Object.fromEntries(new FormData(e.currentTarget)));const ok=persist();close();profile(id);if(ok)notify('Project saved to your local portfolio.')})}
function review(id){modal('Share your experience.',`<form id="review-form"><div class="field-row"><div class="field"><label for="review-name">Your name</label><input id="review-name" name="name" required></div><div class="field"><label for="review-rating">Overall rating</label><select id="review-rating" name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${n} out of 5</option>`).join('')}</select></div></div><div class="field"><label for="review-project">Project you worked on together</label><input id="review-project" name="project" required></div><div class="field"><label for="review-text">Your remarks</label><textarea id="review-text" name="text" required placeholder="Quality, delivery, communication, and anything future clients should know."></textarea></div><label class="review-confirm"><input type="checkbox" required>I’m describing my own experience. This is an unverified local preview review.</label><button type="submit" class="button small primary">Save review locally</button></form>`);document.getElementById('review-form').addEventListener('submit',e=>{e.preventDefault();const r=Object.fromEntries(new FormData(e.currentTarget));r.rating=Number(r.rating);r.date=new Date().toISOString().slice(0,10);(localReviews[id]??=[]).push(r);const ok=persist();close();profile(id);if(ok)notify('Unverified review saved locally.')})}
function request(id){const s=all().find(x=>x.id===id);if(!s)return;modal('A brief for '+safe(s.name),`<p>Prepare a request addressed to ${safe(s.contact)}. No email will be sent from this preview.</p><form id="profile-enquiry"><div class="field"><label for="request-sender">Your name / organisation</label><input id="request-sender" name="sender" required></div><div class="field"><label for="request-reply">Your reply email</label><input id="request-reply" type="email" name="reply" required></div><div class="field"><label for="request-brief">Requirements, quantity, location and deadline</label><textarea id="request-brief" name="brief" required></textarea></div><button class="button small primary" type="submit">Prepare request</button></form>`);document.getElementById('profile-enquiry').addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));const body=`Hi ${s.contact},\n\n${f.brief}\n\nPlease share your itemised quotation, delivery schedule, payment terms and exclusions with ${f.reply}.\n\nRegards,\n${f.sender}`;modal('Your quotation request.',`<span class="chip gold">Prepared · Not sent</span><p>To: ${safe(s.email)}</p><label class="visually-hidden" for="request-text">Quotation request draft</label><textarea id="request-text" class="email-body">${safe(body)}</textarea><button class="button small primary" data-copy-request>Copy request</button>`);modalRoot.querySelector('[data-copy-request]').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.getElementById('request-text').value);notify('Request copied.')}catch{document.getElementById('request-text').select();notify('Select and copy the text manually.')}})})}
document.addEventListener('click',e=>{const anchor=e.target.closest('.portfolio-anchor-nav a');if(anchor){e.preventDefault();document.querySelector(anchor.getAttribute('href'))?.scrollIntoView({behavior:'smooth'});return}const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-supplier-signup'))signup();if(b.hasAttribute('data-close-supplier'))close();if(b.dataset.profile){location.hash=b.dataset.profile;profile(b.dataset.profile);window.scrollTo({top:0,behavior:'instant'})}if(b.hasAttribute('data-directory')){history.replaceState(null,'',location.pathname);directory()}if(b.dataset.editBusiness)editBusiness(b.dataset.editBusiness);if(b.dataset.addProject)addProject(b.dataset.addProject);if(b.dataset.review)review(b.dataset.review);if(b.dataset.request)request(b.dataset.request)});
document.addEventListener('keydown',e=>{const m=modalRoot.querySelector('.modal');if(!m)return;if(e.key==='Escape')close();if(e.key==='Tab'){const els=[...m.querySelectorAll('input,textarea,select,button')];if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}});
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);id?profile(id):directory()});
window.getQuoteLensContext=()=>({view:'suppliers',title:selectedId?all().find(s=>s.id===selectedId)?.name:'Supplier directory'});
location.hash?profile(location.hash.slice(1)):directory();
})();
